from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)

        prefix = []
        total = 0
        for s in skill:
            total += s
            prefix.append(total)

        start = 0

        for j in range(1, len(mana)):
            prev_mana = mana[j - 1]
            curr_mana = mana[j]

            wait = prev_mana * prefix[0]
            prev_prefix = 0

            for i in range(1, n):
                prev_prefix = prefix[i - 1]
                wait = max(wait, prev_mana * prefix[i] - curr_mana * prev_prefix)

            start += wait

        return start + mana[-1] * prefix[-1]
